corpus_block("test-coord-polar.R: radial coords can be reversed", {
  .plot("test-coord-polar.R: radial coords can be reversed #1", p <- ggplot(data_frame0(x = c(0, 2), y = c(0, 2))) +
      aes(x = x, y = y) +
      geom_point() +
      scale_x_continuous(limits = c(-1, 3), expand = c(0, 0)) +
      scale_y_continuous(limits = c(-1, 3), expand = c(0, 0)) +
      theme_test() +
      theme(axis.line = element_line()))
  fwd <- coord_radial(start = 0.5 * pi, end = 1.5 * pi, reverse = "none")
  rev <- coord_radial(start = 0.5 * pi, end = 1.5 * pi, reverse = "thetar")
  .plot("test-coord-polar.R: radial coords can be reversed #2", p + rev)
  .plot("test-coord-polar.R: radial coords can be reversed #3", p + fwd)
  fwd <- layer_grob(p + fwd)[[1]]
  .plot("test-coord-polar.R: radial coords can be reversed #4", p + rev)
  rev <- layer_grob(p + rev)[[1]]
})

