corpus_block("test-coord-polar.R: polar coordinates draw correctly", {
  theme <- theme_test() +
      theme(
        axis.text.y = element_blank(),
        axis.title = element_blank(),
        panel.grid.major = element_line(colour = "grey90")
      )
  dat <- data_frame(x = rep(0:1, 4), y = rep(c(1, 10, 40, 80), each = 2))
  .plot("test-coord-polar.R: polar coordinates draw correctly #1", ggplot(dat, aes(x, y, group = factor(y))) + geom_path() + coord_polar() + theme)
  dat <- data_frame(
      theta = c(0, 2*pi,   2,   6, 6, 1,    1,  0),
      r     = c(0,    0, 0.5, 0.5, 1, 1, 0.75, 0.5),
      g     = 1:8
    )
  .plot("test-coord-polar.R: polar coordinates draw correctly #2", ggplot(dat, aes(theta, r, colour = g)) + geom_path(show.legend = FALSE) + geom_point(colour = "black") + 
      coord_polar() + theme)
  dat <- data_frame(x = LETTERS[1:3], y = 1:3)
  .plot("test-coord-polar.R: polar coordinates draw correctly #3", ggplot(dat, aes(x, y)) + geom_bar(stat = "identity") + coord_polar() + theme)
  .plot("test-coord-polar.R: polar coordinates draw correctly #4", ggplot(dat, aes(x, y)) + geom_bar(stat = "identity") + coord_polar(theta = "y") + 
      theme)
  .plot("test-coord-polar.R: polar coordinates draw correctly #5", ggplot(dat, aes(x, y)) + geom_bar(stat = "identity") + coord_polar(theta = "y") + 
      scale_x_discrete(expand = c(0, 0.6)) + theme)
  .plot("test-coord-polar.R: polar coordinates draw correctly #6", ggplot(dat, aes(x, y, group = factor(y))) + geom_blank() + scale_y_continuous(sec.axis = sec_axis(~. * 
      0.1, name = "sec y")) + coord_polar() + theme_test() + theme(axis.text.x = element_blank()))
})

corpus_block("test-coord-polar.R: coord_radial() draws correctly", {
  theme <- theme(
      axis.line.theta = element_line(colour = "tomato"),
      axis.line.r   = element_line(colour = "dodgerblue"),
    )
  sec_guides <- guides(
      r.sec = guide_axis(
        theme = theme(axis.line.r = element_line(colour = "orchid"))
      ),
      theta.sec = guide_axis_theta(
        theme = theme(axis.line.theta = element_line(colour = "limegreen"))
      )
    )
  .plot("test-coord-polar.R: coord_radial() draws correctly #1", p <- ggplot(mtcars, aes(disp, mpg)) +
      geom_point() +
      theme)
  .plot("test-coord-polar.R: coord_radial() draws correctly #2", {
      p + coord_radial(inner.radius = 0.3, r.axis.inside = FALSE) + sec_guides
  })
  .plot("test-coord-polar.R: coord_radial() draws correctly #3", {
      p + coord_radial(start = 0.25 * pi, end = 0.75 * pi, inner.radius = 0.3, r.axis.inside = TRUE, 
          theta = "y") + sec_guides
  })
  df <- data_frame0(
      x = 1:5, lab = c("cat", "strawberry\ncake", "coffee", "window", "fluid")
    )
  .plot("test-coord-polar.R: coord_radial() draws correctly #4", ggplot(df, aes(x, label = lab)) +
      geom_text(aes(y = "0 degrees"),  angle = 0) +
      geom_text(aes(y = "90 degrees"), angle = 90) +
      coord_radial(start = 0.5 * pi, end = 1.5 * pi,
                   rotate.angle = TRUE) +
      theme)
  .plot("test-coord-polar.R: coord_radial() draws correctly #5", ggplot(df, aes(x, label = lab)) + geom_text(aes(y = "0 degrees"), angle = 0) + geom_text(aes(y = "90 degrees"), 
      angle = 90) + coord_radial(start = 0.5 * pi, end = 1.5 * pi, rotate.angle = TRUE, 
      r.axis.inside = FALSE) + theme)
})

